## 3. Advanced Reference Qualifier Implementation Example

### Step A: The Script Include (Server-Side)

### Create a client-callable Script Include named CatalogFilterUtils:

JavaScript

var CatalogFilterUtils = Class.create();

CatalogFilterUtils.prototype = Object.extendsObject(AbstractScriptInclude, {

/**

* Returns a string of sys_ids matching location criteria

* @param {string} locationId - Sys_id of location selected in form

* @return {string} Encoded query string (sys_idIN...)

*/

getAvailableDevices: function(locationId) {

var deviceList = [];

if (!locationId) {

return 'sys_id=NULL'; // Returns empty list if no location provided

}

```javascript
var ciGr = new GlideRecord('cmdb_ci_hardware');
```

ciGr.addQuery('location', locationId);

ciGr.addQuery('install_status', 1); // Installed status

ciGr.query();

while (ciGr.next()) {

deviceList.push(ciGr.sys_id.toString());

}

return 'sys_idIN' + deviceList.join(',');

},

type: 'CatalogFilterUtils'

});

### Step B: Variable Configuration

In the Reference Variable configuration form:

### Type: Reference

### Reference Table: Hardware (cmdb_ci_hardware)

### Use Reference Qualifier: Advanced

### Reference Qual:

JavaScript

javascript:new CatalogFilterUtils().getAvailableDevices(current.variables.location);

